gTN(){return"\u0418\u04d9. \u0411\u0435\u043b\u0433\u0456 \u0436\u043e\u043b\u0434\u0430 \u0431\u0430\u043b\u0430\u043b\u0430\u0440 \u043f\u0430\u0439\u0434\u0430 \u0431\u043e\u043b\u0443\u044b \u043c\u04af\u043c\u043a\u0456\u043d \u0430\u0439\u043c\u0430\u049b \u0442\u0443\u0440\u0430\u043b\u044b \u0435\u0441\u043a\u0435\u0440\u0442\u0435\u0434\u0456."},
